Algorithme EvaluationMention;
Var
    note : Reel;
Debut
    // Lecture de la note saisie par l'utilisateur
    Ecrire("Entrez la note de l'étudiant (0 à 20) :");
    Lire(note);

    // Prise de décision conditionnelle imbriquée
    Si (note >= 16) Alors
        Ecrire("Mention Très Bien");
    Sinon Si (note >= 14) Alors
        Ecrire("Mention Bien");
    Sinon Si (note >= 12) Alors
        Ecrire("Mention Assez Bien");
    Sinon Si (note >= 10) Alors
        Ecrire("Mention Passable");
    Sinon
        Ecrire("Ajourné (Insuffisant)");
    Fin Si; Fin Si; Fin Si; Fin Si;
Fin.

Algorithme DemonstrationBoucles;
Var
    i, N, Somme, Saisie : Entier;
Debut
    // 1. BOUCLE POUR : Calcul de la somme de 1 à N
    Ecrire("Donnez N :");
    Lire(N);
    Somme := 0;
    Pour i := 1 a N Faire
        Somme := Somme + i;
    Fin Pour;
    Ecrire("Somme 1 a N = ", Somme);

    // 2. BOUCLE TANTQUE : Compte à rebours
    TantQue (N > 0) Faire
        Ecrire("T-moins : ", N);
        N := N - 1; // Modification de la condition pour éviter une boucle infinie !
    Fin TantQue;

    // 3. BOUCLE REPETER : Saisie sécurisée d'un nombre entre 1 et 10
    Repeter
        Ecrire("Saisir un nombre valide (entre 1 et 10) :");
        Lire(Saisie);
    Jusqua (Saisie >= 1 Et Saisie <= 10);
    Ecrire("Saisie valide enregistrée : ", Saisie);
Fin.

Algorithme SwapVariables;
Var
    A, B, Temp : Entier;
Debut
    A := 15;
    B := 42;
    Ecrire("Avant la permutation : A = ", A, " et B = ", B);

    // Processus de permutation sécurisé
    Temp := A;  // 1. Sauvegarde de la valeur initiale de A
    A := B;     // 2. Copie de B dans A
    B := Temp;  // 3. Restitution de la valeur initiale de A dans B

    Ecrire("Après la permutation : A = ", A, " et B = ", B);
Fin.
